/* PC端：头像底=分割线；计数器在名字与分割线之间上下等距；整体蒙版无接缝 */
@media screen and (min-width: 1001px) {
  #chat .mes {
    position: relative !important;
    display: block !important;
    padding-left: 72px !important;
    padding-right: calc(72px - 6px) !important; /* 补偿滚动条轨道 */
    padding-top: 4px !important;
    margin-bottom: 18px !important;
    box-sizing: border-box !important;
    --pc-avatar: 56px;
    --pc-name-h: 1.2em;
    --pc-chip-h: calc(var(--mainFontSize) * 0.78 * 1.3 + 6px);
    --pc-gap: calc((var(--pc-avatar) - var(--pc-name-h) - var(--pc-chip-h)) / 2);
  }
  /* 角落分界(圆角)：右下角，收 66px 到正文右缘，last_mes 除外 */
  #chat .mes:not(.last_mes)::after {
    content: "" !important;
    position: absolute !important;
    width: 20px !important;
    height: 20px !important;
    pointer-events: none !important;
    z-index: 1 !important;
    bottom: 0 !important;
    right: calc(72px - 6px) !important;
    opacity: calc(var(--avatar-mode)) !important; /* 大卡模式隐藏,传统模式保留 */
    border-bottom: 1.5px solid var(--SmartThemeEmColor) !important;
    border-right: 1.5px solid var(--SmartThemeEmColor) !important;
    border-bottom-right-radius: 7px !important;
  }
  /* 容器定位在芯片行；头像绝对拉回左上 */
  .mesAvatarWrapper {
    position: absolute !important;
    left: 72px !important;
    top: calc(4px + var(--pc-name-h) + var(--pc-gap) - 1px) !important;
    right: auto !important;
    width: max-content !important;
    max-width: calc(100% - 96px) !important;
    min-width: 0 !important;
    height: var(--pc-chip-h) !important;
    flex: none !important;
    display: flex !important;
    flex-direction: row !important;
    flex-wrap: nowrap !important;
    align-items: center !important;
    gap: 0 !important;
    z-index: 5 !important;
    pointer-events: none !important;
    overflow: visible !important;
  }
  .mesAvatarWrapper .avatar {
    position: absolute !important;
    left: -64px !important;
    top: calc(-1 * (var(--pc-name-h) + var(--pc-gap))) !important;
    width: var(--pc-avatar) !important;
    height: var(--pc-avatar) !important;
    min-width: var(--pc-avatar) !important;
    min-height: var(--pc-avatar) !important;
    margin: 0 !important;
    pointer-events: auto !important;
    transform: none !important;
  }
  .mesAvatarWrapper .avatar img {
    width: var(--pc-avatar) !important;
    height: var(--pc-avatar) !important;
  }
  .mesAvatarWrapper::after {
    content: none !important;
    display: none !important;
  }
  #chat .mes .mes_block {
    display: block !important;
    padding: 0 !important;
    width: 100% !important;
    box-sizing: border-box !important;
  }
  /* 名字区高度=头像高，底边=头像底=分割线 */
  #chat .mes .ch_name {
    position: relative !important;
    display: flex !important;
    flex-direction: row !important;
    flex-wrap: nowrap !important;
    align-items: flex-start !important;
    justify-content: space-between !important;
    height: var(--pc-avatar) !important;
    min-height: var(--pc-avatar) !important;
    max-height: var(--pc-avatar) !important;
    padding: 0 !important;
    margin: 0 0 10px 0 !important;
    box-sizing: border-box !important;
    overflow: visible !important;
  }
  #chat .mes .ch_name > .flex-container.flex1,
  #chat .mes .ch_name > .flex1 {
    flex: 1 1 auto !important;
    min-width: 0 !important;
    max-width: calc(100% - 4em) !important;
    display: flex !important;
    align-items: center !important;
    height: var(--pc-name-h) !important;
  }
  #chat .mes .ch_name .alignItemsBaseline {
    display: flex !important;
    flex-wrap: nowrap !important;
    align-items: center !important;
    column-gap: 8px !important;
    width: 100% !important;
  }
  #chat .mes .ch_name .name_text {
    flex: 0 1 auto !important;
    min-width: 0 !important;
    line-height: var(--pc-name-h) !important;
  }
  #chat .mes .timestamp {
    display: inline-flex !important;
    align-items: center !important;
    white-space: nowrap !important;
    flex: 0 0 auto !important;
    font-size: calc(var(--mainFontSize) * 0.85) !important;
    opacity: 0.8 !important;
    line-height: 1.2 !important;
  }
  #chat .mes .timestamp-icon {
    display: inline-block !important;
    width: 1em !important;
    height: 1em !important;
    flex: 0 0 1em !important;
    margin-left: 4px !important;
    vertical-align: middle !important;
  }
  #chat .mes .timestamp-icon svg {
    width: 1em !important;
    height: 1em !important;
    display: inline-block !important;
    vertical-align: middle !important;
  }

  #chat .mes .ch_name::after {
    content: "" !important;
    position: absolute !important;
    left: 0 !important;
    right: 0 !important;
    bottom: 0 !important;
    height: 1px !important;
    width: 100% !important;
    background-color: var(--SmartThemeEmColor) !important;
    opacity: 0.35 !important;
    z-index: 1 !important;
  }
  /* 整体蒙版：在 wrapper flex 内横排，无接缝、不重叠 */
  #chat .mes .mesIDDisplay,
  #chat .mes .mes_timer,
  #chat .mes .tokenCounterDisplay {
    position: static !important;
    display: inline-block !important;
    top: auto !important;
    left: auto !important;
    margin: 0 !important;
    padding: 2px 8px !important;
    font-weight: 500 !important;
    font-size: calc(var(--mainFontSize) * 0.78) !important;
    opacity: 0.85 !important;
    line-height: 1.3 !important;
    white-space: nowrap !important;
    max-width: none !important;
    overflow: visible !important;
    background: color-mix(in srgb, var(--SmartThemeBorderColor) 60%, transparent) !important;
    border-radius: 0 !important;
    z-index: 5 !important;
    pointer-events: auto !important;
    box-sizing: border-box !important;
  }
  #chat .mes .mesIDDisplay {
    border-radius: 4px 0 0 4px !important;
  }
  #chat .mes .tokenCounterDisplay:not(:empty) {
    border-radius: 0 4px 4px 0 !important;
  }
  #chat .mes .mes_timer:empty {
    display: none !important;
  }
  #chat .mes .tokenCounterDisplay:empty {
    display: none !important;
  }
  #chat .mes:has(.mes_timer:empty):has(.tokenCounterDisplay:empty) .mesIDDisplay {
    border-radius: 4px !important;
  }
  #chat .mes:has(.mes_timer:empty) .tokenCounterDisplay:not(:empty) {
    border-radius: 0 4px 4px 0 !important;
  }
  #chat .mes:has(.tokenCounterDisplay:empty) .mes_timer:not(:empty) {
    border-radius: 0 4px 4px 0 !important;
  }
  #chat .mes .mes_text {
    padding-top: calc(var(--mainFontSize) * 0.75) !important;
    padding-bottom: 62px !important; /* 按钮排+swipe行留位，避免短消息时压正文 */
  }
  /* 操作按钮行：钉到正文末尾右下角（定位上下文=mes_block，ch_name 改静态） */
  #chat .mes .mes_block {
    position: relative !important;
    overflow-x: clip !important;
    overflow-y: visible !important;
  }
  #chat .mes .ch_name {
    position: static !important;
  }
  body:not(.documentstyle) #chat .mes .ch_name {
    border-bottom: 1px solid var(--SmartThemeEmColor) !important;
  }
  #chat .mes .ch_name::after {
    display: none !important;
  }
  #chat .mes .ch_name .mes_buttons {
    position: absolute !important;
    top: auto !important;
    bottom: 6px !important;
    right: calc(2px + 0.5em) !important;
    left: auto !important;
    z-index: 30 !important;
  }
  /* 编辑态按钮排：同样钉底部右下角 */
  #chat .mes .mes_edit_buttons {
    float: none !important;
    position: absolute !important;
    bottom: 6px !important;
    right: calc(2px + 0.5em) !important;
    margin: 0 !important;
    z-index: 30 !important;
  }
  /* 编辑态：普通按钮行让位 */
  #chat .mes .mes_block:has(.edit_textarea) .ch_name .mes_buttons {
    display: none !important;
  }
  /* 编辑态正文底距加大：方钮排(~46px)不压正文框 */
  #chat .mes .mes_text:has(.edit_textarea) {
    padding-bottom: 64px !important;
  }
  /* swipe 计数器块：与底部按钮排同行 */
  #chat .mes .swipeRightBlock {
    bottom: 6px !important;
  }
  /* swipe_left：与底部按钮排同高 */
  #chat .mes .swipe_left {
    bottom: 6px !important;
  }
  #chat .mes .mes_media_wrapper:not(:empty),
  #chat .mes .mes_file_wrapper:not(:empty) {
    padding-bottom: 36px !important;
  }

  }
