/* 酒馆助手tagfixer脚本按钮:emoji换Phosphor boxing-glove,固定1.2em盒不撑行 */
#chat .mes .mes_buttons .tagfixer-fix-btn {
  font-size: 0 !important;
  position: relative !important;
  display: inline-block !important;
  /* 1.34=FA字形盒metrics(实测14.25*1.34≈19.1px),与同行FA按钮等高 */
  width: calc(var(--mainFontSize) * 1.34) !important;
  height: calc(var(--mainFontSize) * 1.34) !important;
  padding: 0 !important;
  margin: 0 !important;
  vertical-align: middle !important;
}
#chat .mes .mes_buttons .tagfixer-fix-btn::before {
  content: "" !important;
