  }
  #chat .mes .sp-anchor-btn:hover {
    transform: translateY(calc(-50% - 1px)) !important;
  }
  #chat .mes .sp-anchor-btn .sp-anchor-btn-svg {
    width: 15px !important;
    height: 15px !important;
  }
  /* 移动端:构画按钮浮层贴名字右端(30px占位隔开时间戳),不占行宽→名字+时间戳始终同行 */
  @media screen and (max-width: 1000px) {
    #chat .mes .sp-anchor-btn {
      position: absolute !important;
      right: 0 !important;
      top: 50% !important;
      transform: translateY(-50%) !important;
      width: 22px !important;
      height: 22px !important;
      margin: 0 !important;
      flex: none !important;
    }
    #chat .mes:has(.sp-anchor-btn) .name_text {
      position: relative !important;
      padding-right: 30px !important;
    }
  }

  /* 首页欢迎消息 mode0 不显示大卡(assistant_message 仅欢迎页助手用, 不误伤普通 AI 回复; welcome_prompt 系统欢迎) */
  /* wrapper 高度塌缩+裁剪+透明(mode0), mode1 恢复传统小头像 */
  #chat .mes[type="assistant_message"] .mesAvatarWrapper,
  #chat .mes[type="welcome_prompt"] .mesAvatarWrapper {
    height: calc(0px * (1 - var(--avatar-mode)) + 56px * var(--avatar-mode)) !important;
    min-height: calc(0px * (1 - var(--avatar-mode)) + 56px * var(--avatar-mode)) !important;
    max-height: calc(0px * (1 - var(--avatar-mode)) + 56px * var(--avatar-mode)) !important;
    overflow: hidden !important;
    opacity: calc(0 * (1 - var(--avatar-mode)) + 1 * var(--avatar-mode)) !important;
  }
  #chat .mes[type="assistant_message"]::before,
  #chat .mes[type="welcome_prompt"]::before {
    opacity: 0 !important;
  }
  /* 名字/计数器从卡下回到顶部(mode0), mode1 保持传统 */
  #chat .mes[type="assistant_message"] .mes_block,
  #chat .mes[type="welcome_prompt"] .mes_block {
    padding-top: calc(4px * (1 - var(--avatar-mode)) + 4px * var(--avatar-mode)) !important;
  }
  #chat .mes[type="assistant_message"] .mesIDDisplay,
  #chat .mes[type="assistant_message"] .mes_timer,
  #chat .mes[type="assistant_message"] .tokenCounterDisplay,
  #chat .mes[type="welcome_prompt"] .mesIDDisplay,
  #chat .mes[type="welcome_prompt"] .mes_timer,
  #chat .mes[type="welcome_prompt"] .tokenCounterDisplay {
    margin-top: calc(0px * (1 - var(--avatar-mode)) + 13px * var(--avatar-mode)) !important;
  }
  #chat .mes[type="assistant_message"] .ch_name > .flex-container.flex1,
  #chat .mes[type="assistant_message"] .ch_name > .flex1,
  #chat .mes[type="welcome_prompt"] .ch_name > .flex-container.flex1,
  #chat .mes[type="welcome_prompt"] .ch_name > .flex1 {
    top: calc(4px * (1 - var(--avatar-mode)) + 4px * var(--avatar-mode)) !important;
    left: calc(16px * (1 - var(--avatar-mode)) + 72px * var(--avatar-mode)) !important;
  }

  /* 欢迎消息无卡: mes_text 的卡区分隔线也不留(避免名字行下卡线) */
  #chat .mes[type="assistant_message"] .mes_text,
  #chat .mes[type="welcome_prompt"] .mes_text {
    border-top-width: 0 !important;
  }
  /* 首页欢迎消息: 大卡已隐藏, 名字行一并隐藏(避免孤立的名字+时间戳) */
  #chat .mes[type="assistant_message"] .ch_name,
  #chat .mes[type="welcome_prompt"] .ch_name {
    display: none !important;
  }
  /* 首页欢迎消息: 头像区整体隐藏(头像+计数器), 相框板/分割线一并去掉 */
  #chat .mes[type="assistant_message"] .mesAvatarWrapper,
  #chat .mes[type="welcome_prompt"] .mesAvatarWrapper {
    display: none !important;
  }
  #chat .mes[type="assistant_message"]::before,
  #chat .mes[type="welcome_prompt"]::before {
    display: none !important;
  }
  #chat .mes[type="assistant_message"] .mes_block::after,
  #chat .mes[type="welcome_prompt"] .mes_block::after {
    display: none !important;
  }
